package com.example.rokidgeminisecretary;
import org.json.*;
public class ImageReferenceSummaryTest{
 static int n;static void ok(boolean value,String label){if(!value)throw new AssertionError(label);n++;}
 static JSONObject data(int count,String answer)throws Exception{return new JSONObject().put("at",1000).put("imageCount",count).put("question","この内容は？").put("answer",answer).put("data","must not copy").put("captureContext","must not copy");}
 public static void main(String[]args)throws Exception{
  JSONObject view=ImageReferenceSummary.view(data(2,"【画像1】予約票【画像2】地図"),2000);JSONArray parts=view.getJSONArray("sections");ok(view.getBoolean("available")&&parts.length()==2,"two independent attachments");ok(parts.getJSONObject(0).getString("reading").equals("予約票")&&parts.getJSONObject(1).getString("reading").equals("地図"),"separate actual reading text");ok(!view.has("data")&&!view.has("captureContext"),"no image bytes/location copied");
  view=ImageReferenceSummary.view(data(2,"【画像2】地図"),2000);ok(!view.getJSONArray("sections").getJSONObject(0).getBoolean("separated"),"missing image not invented");ok(view.getString("answer").equals("【画像2】地図"),"original available");
  view=ImageReferenceSummary.view(data(2,"【画像2】地図【画像1】予約票"),2000);ok(!view.getJSONArray("sections").getJSONObject(1).getBoolean("separated"),"out of order headings fail closed");
  view=ImageReferenceSummary.view(data(2,"【画像1】A【画像1】B"),2000);ok(!view.getJSONArray("sections").getJSONObject(0).getBoolean("separated"),"duplicate heading not silently merged");
  ok(ImageReferenceSummary.view(data(1,"全文"),2000).getJSONArray("sections").getJSONObject(0).getString("reading").equals("全文"),"single image retains original");
  ok(!ImageReferenceSummary.view(data(1,"全文"),1000+ImageReferenceSummary.TTL).optBoolean("available"),"exact expiry hidden");ok(!ImageReferenceSummary.view(data(1,"全文"),999).optBoolean("available"),"clock skew hidden");
  boolean bad=false;try{ImageReferenceSummary.checked(data(7,"x"));}catch(IllegalArgumentException e){bad=true;}ok(bad,"invalid count rejected");bad=false;try{ImageReferenceSummary.checked(data(1,"x".repeat(24001)));}catch(IllegalArgumentException e){bad=true;}ok(bad,"overlong reading rejected");
  view=ImageReferenceSummary.view(data(2,"【画像1】A【画像2】B").put("kinds",new JSONArray().put("image").put("video")),2000);ok(view.getJSONArray("sections").getJSONObject(1).getString("kind").equals("video"),"video stays assigned to attachment two");ok(ImageReferenceSummary.view(data(1,"legacy"),2000).getJSONArray("sections").getJSONObject(0).getString("kind").equals("unknown"),"legacy reading kind unknown");
  JSONObject selected=ImageReferenceSummary.view(data(2,"【画像1】A【画像2】B"),2000),latest=new JSONObject(selected.toString());String before=selected.toString();ok(ImageReferenceSummary.sameReference(selected,latest),"matching snapshot");latest.put("at",1001);ok(!ImageReferenceSummary.sameReference(selected,latest),"new reference rejected");latest=new JSONObject(selected.toString()).put("available",false);ok(!ImageReferenceSummary.sameReference(selected,latest),"expired rejected");latest=new JSONObject(selected.toString()).put("answer","different");ok(!ImageReferenceSummary.sameReference(selected,latest),"same timestamp changed reading rejected");latest=new JSONObject(selected.toString()).put("imageCount",1);ok(!ImageReferenceSummary.sameReference(selected,latest),"changed count rejected");ok(!ImageReferenceSummary.sameReference(null,selected),"missing snapshot rejected");ok(selected.toString().equals(before),"snapshot unchanged");
  String key=ImageReferenceSummary.referenceKey(selected);ok(key.matches("[a-f0-9]{64}"),"opaque key");ok(ImageReferenceSummary.matchesKey(key,selected),"current key accepted");ok(!ImageReferenceSummary.matchesKey(key,new JSONObject(selected.toString()).put("available",false)),"expired key rejected");ok(!ImageReferenceSummary.matchesKey(key,new JSONObject(selected.toString()).put("answer","changed")),"same timestamp content change rejected");ok(!ImageReferenceSummary.matchesKey("invalid",selected),"invalid key rejected");ok(!ImageReferenceSummary.matchesKey(key,null),"missing reference rejected");ok(ImageReferenceSummary.referenceKey(new JSONObject(selected.toString())).equals(key),"key survives serialization");
  System.out.println("PASS image reference summary "+n+" checks");
 }
}
